mapper.select:
SELECT id, api_code, request_no, batch_no, `data`, `status`, msg, create_time, update_time,is_clean,is_del
FROM b_marketing_tcyr_transfer_record
WHERE id > #{lastSearchId}
    AND api_code = #{apiCode}
    AND status = #{status}
    AND is_del = 1
    AND is_clean = 0
ORDER BY id ASC
LIMIT #{searchSize}

